		return "", fmt.Errorf("empty workspace URI")
	}

	raw := uriStr
	if strings.HasPrefix(raw, "file://") {
		raw = strings.TrimPrefix(raw, "file://")
	} else if strings.HasPrefix(raw, "file:") {
		raw = strings.TrimPrefix(raw, "file:")
